public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // TODO: read n
        int n=sc.nextInt();
        // TODO: validate input (n > 0)
        if(n<=0){
            System.out.println("Invalid Input");
            return;
        }
        // TODO: read n items (weight, value) into arrays
        int[] weight=new int[n];
        int[] value=new int[n];
        for(int i=0;i<n;i++){
            weight[i]=sc.nextInt();
            value[i]=sc.nextInt();
            if(weight[i]<=0||value[i]<=0){
                System.out.println("Invalid Input");
                return;
            }
        }
        // TODO: read capacity, validate it (>= 0)
        int capacity=sc.nextInt();
        if(capacity<0){
            System.out.println("Invalid Input");
            return;
        }
        // TODO: build a 2D dp table of size (n+1) x (capacity+1)
        int[][] dp=new int[n+1][capacity+1];
        // TODO: fill the table using the 0/1 Knapsack recurrence
        for(int i=1;i<=n;i++){
            for(int w=0;w<=capacity;w++){
               if (weight[i-1]> w){
                dp[i][w]=dp[i-1][w];
               }else{
                dp[i][w]=Math.max(dp[i-1][w],value[i]+dp[i-1][w-weight[i-1]]);
               }
            }
        }
        // TODO: print "Maximum Value: <value>" using dp[n][capacity]
        System.out.println("Maximum Value: "+dp[n][capacity]);
        // TODO: print "Invalid Input" if validation fails
    }
}

